import{c as a,Q as t,j as r,m as s}from"./chunks/framework.DoOjWOm2.js";const p=JSON.parse('{"title":"Hub Claim Guide","description":"Connect your Phlix server to a Phlix Hub for remote access and multi-server management.","frontmatter":{"title":"Hub Claim Guide","description":"Connect your Phlix server to a Phlix Hub for remote access and multi-server management."},"headers":[],"relativePath":"hub/claim-server.md","filePath":"hub/claim-server.md"}'),i={name:"hub/claim-server.md"};function o(n,e,h,l,c,d){return t(),r("div",null,[...e[0]||(e[0]=[s(`<p><strong>Phase:</strong> N (End-User Documentation) <strong>Step:</strong> N.11 <strong>Since:</strong> 0.18.0</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>Claiming links your self-hosted Phlix server to a Phlix Hub account so you can access it remotely without configuring port forwarding or a VPN. As the server admin, you generate a short claim code from your server&#39;s Settings, paste it into the Hub dashboard, and the hub immediately gains access to your server&#39;s libraries and live streams.</p><h2 id="hub-claim-flow" tabindex="-1">Hub Claim Flow <a class="header-anchor" href="#hub-claim-flow" aria-label="Permalink to &quot;Hub Claim Flow&quot;">​</a></h2><p>Work through these steps on both your server and the Hub dashboard.</p><h3 id="_1-—-server-admin-open-hub-settings" tabindex="-1">1 — Server Admin: Open Hub Settings <a class="header-anchor" href="#_1-—-server-admin-open-hub-settings" aria-label="Permalink to &quot;1 — Server Admin: Open Hub Settings&quot;">​</a></h3><p>On your Phlix server, log in as an administrator and navigate to:</p><p><strong>Settings → Hub</strong></p><p>If this is the first time opening Hub settings, you will be prompted to set a friendly server name (e.g., &quot;Living Room Server&quot; or &quot;NAS-Phlix&quot;) which will appear in the Hub dashboard.</p><h3 id="_2-—-server-admin-generate-a-claim-code" tabindex="-1">2 — Server Admin: Generate a Claim Code <a class="header-anchor" href="#_2-—-server-admin-generate-a-claim-code" aria-label="Permalink to &quot;2 — Server Admin: Generate a Claim Code&quot;">​</a></h3><p>Click <strong>Generate Claim Code</strong>.</p><p>A code in the format <code>XXXX-XXXX</code> (four letters, hyphen, four letters) appears on screen with a <strong>10-minute expiry countdown</strong>. The code is case-insensitive.</p><p>Record the code and switch to your Hub dashboard. The countdown begins immediately — complete the Hub dashboard steps before the 10 minutes elapse. If the code expires, generate a new one from the server.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The 10-minute expiry is intentional. A short window reduces the risk of a claim code being intercepted or reused if it has been shared over an insecure channel.</p></div><h3 id="_3-—-hub-dashboard-claim-the-server" tabindex="-1">3 — Hub Dashboard: Claim the Server <a class="header-anchor" href="#_3-—-hub-dashboard-claim-the-server" aria-label="Permalink to &quot;3 — Hub Dashboard: Claim the Server&quot;">​</a></h3><p>Open the Hub dashboard at <code>https://hub.phlix.example.com</code> (replace with your Hub&#39;s actual URL) and navigate to:</p><p><strong>My Servers → Claim a Server</strong></p><p>Enter the claim code from step 2 into the <strong>Claim Code</strong> field and click <strong>Claim</strong>.</p><p>The Hub immediately verifies the code with your server. On success:</p><ul><li>Your server appears in <strong>My Servers</strong> with the name you set in step 1</li><li>The server&#39;s libraries become available to any Hub user you grant access to</li><li>The Hub relay tunnel is established, enabling remote playback</li></ul><h3 id="_4-—-verify-the-connection" tabindex="-1">4 — Verify the Connection <a class="header-anchor" href="#_4-—-verify-the-connection" aria-label="Permalink to &quot;4 — Verify the Connection&quot;">​</a></h3><p>Back on your Phlix server&#39;s <strong>Settings → Hub</strong> page, the status changes to <strong>Connected</strong> and shows the Hub URL you are connected to.</p><p>On the Hub dashboard, the server card shows a green &quot;Online&quot; indicator. Clicking the server opens the Hub&#39;s server detail view, which displays the server&#39;s libraries and current playback status.</p><h2 id="cli-alternative" tabindex="-1">CLI Alternative <a class="header-anchor" href="#cli-alternative" aria-label="Permalink to &quot;CLI Alternative&quot;">​</a></h2><p>Server administrators who prefer the command line can claim using the <code>hub:claim</code> command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/phlix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hub:claim</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --code</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ABCD-1234</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://hub.phlix.example.com</span></span></code></pre></div><ul><li><code>--code</code> — the claim code generated from <strong>Settings → Hub</strong> on the server</li><li><code>--hub</code> — your Hub&#39;s base URL</li></ul><p>On success, the command prints:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Server successfully claimed by Hub https://hub.phlix.example.com</span></span>
<span class="line"><span>Server name: Living Room Server</span></span></code></pre></div><p>To unclaim (disconnect the server from the Hub) without claiming a new one:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/phlix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hub:unclaim</span></span></code></pre></div><p>This removes the server from the Hub account and terminates the relay tunnel. Libraries that were shared via Hub become inaccessible to Hub users immediately.</p><h2 id="what-can-go-wrong" tabindex="-1">What Can Go Wrong <a class="header-anchor" href="#what-can-go-wrong" aria-label="Permalink to &quot;What Can Go Wrong&quot;">​</a></h2><h3 id="claim-code-has-expired" tabindex="-1">Claim code has expired <a class="header-anchor" href="#claim-code-has-expired" aria-label="Permalink to &quot;Claim code has expired&quot;">​</a></h3><p><strong>Symptom:</strong> The Hub dashboard shows &quot;Claim code is invalid or has expired&quot; when you try to submit the code.</p><p><strong>Fix:</strong> Return to your server&#39;s <strong>Settings → Hub</strong> and click <strong>Generate Claim Code</strong> to get a fresh code. Work quickly — the new code also expires after 10 minutes. Ensure you start the Hub dashboard step before generating a new code so the window is as short as possible.</p><h3 id="server-has-already-been-claimed" tabindex="-1">Server has already been claimed <a class="header-anchor" href="#server-has-already-been-claimed" aria-label="Permalink to &quot;Server has already been claimed&quot;">​</a></h3><p><strong>Symptom:</strong> The Hub dashboard shows &quot;This server has already been claimed by another Hub account.&quot;</p><p><strong>Fix:</strong> A server can only be claimed by one Hub account at a time. To transfer ownership, the current Hub admin must first unclaim the server from <strong>My Servers → [server name] → Settings → Unclaim Server</strong>. Once unclaimed, any Hub account can claim it.</p><h3 id="network-isolation-—-server-cannot-reach-the-hub" tabindex="-1">Network isolation — server cannot reach the Hub <a class="header-anchor" href="#network-isolation-—-server-cannot-reach-the-hub" aria-label="Permalink to &quot;Network isolation — server cannot reach the Hub&quot;">​</a></h3><p><strong>Symptom:</strong> The Hub dashboard spins indefinitely after you submit the claim code, then reports &quot;Could not reach server.&quot;</p><p><strong>Fix:</strong> The server needs outbound HTTPS access to the Hub&#39;s URL (port 443). Check that your server&#39;s firewall allows outbound HTTPS connections. If the server is on an isolated network, a proxy or VPN may be required for initial claim. After the claim, the Hub maintains its own outbound relay tunnel so ongoing remote access does not depend on the server initiating outbound connections.</p><h3 id="claim-code-entered-incorrectly" tabindex="-1">Claim code entered incorrectly <a class="header-anchor" href="#claim-code-entered-incorrectly" aria-label="Permalink to &quot;Claim code entered incorrectly&quot;">​</a></h3><p><strong>Symptom:</strong> &quot;Invalid claim code&quot; even though you are certain the code was entered correctly.</p><p><strong>Fix:</strong> Claim codes are case-insensitive, but hyphens are required — format must be <code>XXXX-XXXX</code>. If you are copy-pasting, ensure no extra spaces or invisible characters were included. Generate a fresh code and try again, entering it manually to rule out clipboard issues.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./remote-access.html">Hub remote access</a> — Access your server from outside your home network using the Hub relay</li><li><a href="https://hub.phlix.example.com/admin" target="_blank" rel="noreferrer">Hub administration</a> — Manage connected servers, users, and relay bandwidth from the Hub admin panel</li><li><a href="./../libraries/overview.html">Libraries overview</a> — Add or manage media libraries after your server is connected</li></ul>`,47)])])}const m=a(i,[["render",o]]);export{p as __pageData,m as default};
